"""Invoice totals from a semicolon-separated export."""


def parse_line(line):
    """Parse sku;qty;unit_price into a dict."""
    sku, qty, price = line.strip().split(";")
    try:
        unit = float(price.replace(",", ""))
    except ValueError:
        unit = None
    return {"sku": sku, "qty": int(qty), "unit": unit}


def line_total(item):
    return round(item["qty"] * item["unit"], 2)


def format_total(items):
    return f"{sum(line_total(item) for item in items):.2f}"

